/** One network's indexing. */
export interface NetworkHealth {
  /**
   * How many of its RPC nodes are enabled; 0: no call can go out, its
   * index job idles (its reason says so) and its payments wait.
   */
  enabled_endpoints: number;
  indexing: NetworkIndexing | null;
  /** The indexed chain and network. */
  network: Network;
}

/**
 * One network's indexing: what its indexer last wrote (its `network_index`
 * row) and why its index job last failed.
 */
export interface NetworkIndexing {
  /** Blocks kept. */
  blocks: number;
  /** Unix ms of the indexer's last read whose tip moved; always present. */
  checked_at: number | null;
  /**
   * `tip - confirmations` (saturating), written with it; always present,
   * null with it.
   */
  confirmed: number | null;
  /** Failed steps. */
  failures: number;
  /** The last kept block; always present, null: none yet. */
  indexed: number | null;
  /**
   * Why its index job's last run failed or idles (the job's `reason`),
   * cleared by the next run that does not; always present, null: none.
   */
  job_reason: string | null;
  /** Kept blocks reorged because the chain took them back. */
  reorgs: number;
  /**
   * The node's newest block at the indexer's last read; always present,
   * null: no tip known yet (the job failed before its first).
   */
  tip: number | null;
}

/** Every stored network. */
export interface NetworkList {
  /** Every chain this server runs, which `POST /v1/networks` takes. */
  chains: string[];
  /** Networks in chain, then name, order. */
  networks: ConfiguredNetwork[];
}

/** One node to add, and its network. */
export interface NetworkNode {
  chain: string;
  /** The node's URL, written as `endpoints` writes one. */
  endpoint: string;
  network: string;
}

/** A network's routed methods. */
export interface NetworkRoutes {
  network: Network;
  /** By method; each one's nodes in failover order. */
  routes: RpcRoute[];
}

/** `GET /v1/networks/{chain}/{network}/transactions`: a page of transactions. */
export interface NetworkTransactions {
  /**
   * Pass as `cursor` for the next page; null on the last page. Always
   * present.
   */
  next_cursor: string | null;
  /** The transactions, with their legs. */
  transactions: Transaction[];
}

/** `POST /v1/networks` body. */
export interface NewNetwork {
  /** The chain's block (slot) time, in milliseconds. */
  block_time_ms: number;
  /** A chain of `GET /v1/networks`' `chains`. */
  chain: string;
  /**
   * The chain's own id of the network, as its nodes report it: the EVM
   * chain id, the Solana or Tron genesis hash; null or empty for
   * Bitcoin, which the name identifies.
   */
  chain_id?: string | null;
  /** Positions below the tip before a block counts as confirmed. */
  confirmations: number;
  native: NativeAsset;
  /**
   * The network's name: 1 to 64 of `a-z`, `0-9` and `-` (`my-devnet`).
   * Bitcoin's names its network (`mainnet`, `testnet`, `signet`,
   * `regtest`).
   */
  network: string;
  /** Whether its coins are test coins. */
  testnet: boolean;
}

/** `GET /v1/recovery`: whether a passphrase is set, never its words. */
export interface Recovery {
  /** When it was created (Unix ms); absent when none is set. */
  created_at?: number | null;
  /** Whether a passphrase is set. */
  set: boolean;
}

/** `POST /v1/recovery`: the words, shown this once. */
export interface RecoveryCreated {
  /**
   * 12 BIP39 English words, space-separated. Only their hash is kept:
   * they are never shown again.
   */
  passphrase: string;
}

/** The health of every indexed network. */
export interface Report {
  /** Every indexed network. */
  networks: NetworkHealth[];
  /** At least one network has an index, and no index job has a reason. */
  ready: boolean;
}

/** `POST /v1/networks/endpoints` body. */
export interface RpcAdditions {
  /** Nodes to append, each after its network's current ones, in order. */
  nodes: NetworkNode[];
}

/** One stored node of a network, with its counts and state. */
export interface RpcNode {
  disabled: RpcNodeFailure | null;
  /** Its id: what a route and removal name. */
  id: number;
  /** Its failover position, lowest first. */
  position: number;
  /** Its calls. */
  stats: RpcNodeStats;
  /** Its URL as stored. */
  url: string;
}

/** One record of one node. */
export interface RpcNodeFailure {
  /** When, Unix ms. */
  at: number;
  /** The node's id. */
  endpoint_id: number;
  /** Its id, newest highest; 0 until stored. */
  id: number;
  /**
   * What: `http_401`, `http_403`, `http_404`, `rpc_{code}` (an error
   * object of such a code), `wrong_chain` (the node serves another
   * chain) or `manual` (a disable by hand), each disabling it; or
   * `enabled` (an enable by hand).
   */
  kind: string;
  /** Why, as shown; never a URL. */
  message: string;
}

/**
 * `GET /v1/networks/{chain}/{network}/endpoints/{id}/failures`: a page of
 * what disabled or enabled a node.
 */
export interface RpcNodeFailureList {
  /** The node's records, newest first. */
  failures: RpcNodeFailure[];
  /**
   * Pass as `cursor` for the next page; null on the last page. Always
   * present.
   */
  next_cursor: string | null;
}

/** What a node reports about itself. */
export interface RpcNodeInfo {
  /**
   * The chain it serves, as the network's `chain_id` writes it (EVM
   * chain id, Solana or Tron genesis hash), or its name for Bitcoin: the
   * network's.
   */
  chain_id: string;
  /** Its newest block (or slot). */
  tip: number;
}

/** Whether the transport uses a node. */
export type RpcNodeState = "enabled" | "disabled";

/** One node's counts. */
export interface RpcNodeStats {
  /** HTTP requests that reached it and finished. */
  calls: number;
  /** The node's id. */
  endpoint_id: number;
  /** Of those, the ones that failed. */
  failed_calls: number;
  /** Unix ms of the last; when the node was stored if none. */
  updated_at: number;
}

/** `POST /v1/networks/{chain}/{network}/endpoints/test` body. */
export interface RpcNodeTest {
  /** The node's URL, written as `endpoints` writes one. */
  url: string;
}

/** `POST` and `PUT /v1/networks/{chain}/{network}/endpoints` body. */
export interface RpcNodes {
  /**
   * One to 16 distinct node URLs, in failover order. A URL carries everything:
   * userinfo (HTTP Basic), query keys, a key in the path,
   * `header.<Name>=value` parameters sent as headers, and `rpc.` settings
   * (`timeout_ms`, `max_request_bytes`, `max_response_bytes`, `max_batch`,
   * `rps`: most calls a second, e.g. `3.5`; a request waits for its turn).
   */
  endpoints: string[];
}

/** One method and the endpoints taking turns serving it. */
export interface RpcRoute {
  /** The network's endpoints taking turns, by id. */
  endpoint_ids: number[];
  /** The JSON-RPC method, exactly as sent, e.g. `getBlock`. */
  method: string;
}

/** `PUT /v1/networks/{chain}/{network}/routes` body. */
export interface RpcRoutes {
  /**
   * Every route of the network; empty: none. A method appears once, over
   * one or more of the network's node ids, each once.
   */
  routes: RpcRoute[];
}

/** One send job of a run. */
export interface RunJob {
  /** The job id: `GET /v1/jobs/{id}` reads it. */
  id: string;
  /**
   * Why it failed, or why its last attempt is being retried; always
   * present.
   */
  reason: string | null;
  state: JobState;
}

/** Where a run's jobs are together. */
export type RunOutcome = "pending" | "succeeded" | "failed" | "mixed";

/** A secret setting as listed: never its value or default. */
export interface SecretSetting {
  /** What it is for: its declaration's doc comment. */
  description: string;
  /** Its name: `recovery_passphrase`. */
  key: string;
  /** Whether it has been set. */
  set: boolean;
}

/**
 * `POST /v1/wallets/{id}/transactions` body: one payment from the path's
 * wallet in one asset.
 */
export interface Send {
  /** Exact positive decimal in display units. */
  amount: string;
  /** An asset id of the wallet's network; default `native`. */
  asset?: string;
  /** Recipient address text, as the wallet's chain writes it. */
  destination: string;
  /**
   * How fast it should land; each chain prices it its own way. Default
   * `normal`.
   */
  fee?: FeeLevel;
}

/** An enqueued send. */
export interface SendAccepted {
  /** The send job; `GET /v1/jobs/{id}` reports it. */
  job: string;
}

/** One hour of this server's time. */
export interface ServerHour {
  /** Jobs that failed for good in it. */
  failed: number;
  /** Trigger runs started in it. */
  runs: number;
  /** Its start, Unix seconds. */
  start: number;
  /** Jobs that succeeded in it. */
  succeeded: number;
}

/** The caller's session, decoded and checked. */
export interface SessionRead {
  /**
   * How its login proved who it is (`pwd` or `passphrase`, then `otp`);
   * empty for a key's.
   */
  amr: Amr[];
  /** Unix seconds; a key's bearer secret: now. */
  expires_at: number;
  /** Unix seconds. */
  issued_at: number;
  /** Its key, when a key issued it. */
  key?: UserKey;
  /** Who issued it. */
  kind: Issuer;
  /** What it may do, packed. */
  scopes: Record<string, string[]>;
  /** Who it is for; always present, null: not said. */
  sub: string | null;
  /** Its user. */
  user: User;
}

/** `PATCH /v1/markets/{name}` body. */
export interface SetMarketRequest {
  /** Whether it is asked for quotes. */
  feed: boolean;
}

/** `PUT /v1/networks/{chain}/{network}/endpoints/{id}/state` body. */
export interface SetRpcNodeState {
  /** Why, kept in its records (`failures`); none: `by hand`. */
  reason?: string | null;
  /**
   * `disabled`: no call goes to it, its routes skip it (a `manual`
   * record); `enabled`: used again, its reason cleared (an `enabled`
   * record).
   */
  state: RpcNodeState;
}

/** A setting as listed: its key, value, default and declaration. */
export interface Setting {
  /** Its default, JSON of its type. */
  default: unknown;
  /** What it is for: its declaration's doc comment. */
  description: string;
  /** Its name: `instance`. */
  key: string;
  /** Whether its value may be sent in any response, to anyone. */
  public: boolean;
  /** Its Rust type, as declared: `String`. */
  type: string;
  /** Its value, JSON of its type; the default when never written. */
  value: unknown;
}

/** `GET /v1/settings`. */
export interface SettingList {
  /**
   * Every setting, in declaration order: a secret one as `{key, set,
   * description}` only.
   */
  settings: Listed[];
}

/** `GET /v1/stats`. */
export interface Stats {
  /** Distinct addresses indexed, keyed or watch-only. */
  addresses: number;
  /** Blocks kept. */
  blocks: number;
  /**
   * The last day of chain time (up to the newest kept block), hour by
   * hour, oldest first.
   */
  chain: ChainHour[];
  /** Of those, how many are enabled. */
  enabled: number;
  /** Jobs by where they are. */
  jobs: JobCounts;
  /** Legs kept: movements and rewards. */
  movements: number;
  /** Transactions kept pending. */
  pending: number;
  /** Of those, how many reverted. */
  reverted: number;
  /** The last day of this server's time, hour by hour, oldest first. */
  server: ServerHour[];
  /** Tags on addresses. */
  tags: number;
  /** Transactions kept mined. */
  transactions: number;
  /** Triggers kept. */
  triggers: number;
  /** Wallets whose key is kept. */
  wallets: number;
}

/**
 * One network as stored: its `network` row, its `network_asset` rows, its
 * routes, its index and its `network_endpoint` nodes with their counts and
 * state.
 */
export interface StoredNetwork {
  /** Its native currency and tokens. */
  assets: NetworkAsset[];
  /** The chain's block (slot) time, in milliseconds. */
  block_time_ms: number;
  /** Chain name. */
  chain: string;
  /**
   * The chain's own id of the network (Ethereum chain id, Solana genesis
   * hash); always present, null where the name is enough.
   */
  chain_id: string | null;
  /** Positions below the tip before a block counts as confirmed. */
  confirmations: number;
  /** Whether the server starts indexing it. */
  enabled: boolean;
  /**
   * Its nodes as stored, in failover order; none enabled: no call can go
   * out, its index job idles and its payments wait.
   */
  endpoints: RpcNode[];
  /**
   * An address's explorer page, `{address}` filled in; always present,
   * null: none.
   */
  explorer_address: string | null;
  /**
   * A transaction's explorer page, `{tx}` filled in; always present,
   * null: none.
   */
  explorer_transaction: string | null;
  index: NetworkIndexing | null;
  /**
   * How many positions below the tip a wallet's start may be; at least
   * `confirmations`. Always present, null: no limit. Null on a chain that
   * reads balances (Solana, Ethereum): its line is the chain's final block.
   */
  max_depth: number | null;
  /** Network name. */
  network: string;
  /**
   * Its routed methods, each over its own nodes; every other method goes
   * to all of them.
   */
  routes: RpcRoute[];
  /** The chain's own knobs; an absent key is the chain's default. */
  settings: unknown;
  /** Whether its coins are test coins. */
  testnet: boolean;
}

/** `GET /v1/wallets/tags`: a page of tags. */
export interface TagList {
  /**
   * Pass as `cursor` for the next page; null on the last page. Always
   * present.
   */
  next_cursor: string | null;
  /**
   * Tags in use on any wallet, sorted, each once. A wallet's own tags are
   * on it (`GET /v1/wallets`).
   */
  tags: string[];
}

/**
 * A kept transaction: its `transaction` row and its kept legs. The API
 * shows it as is. Read in one query: its legs come as a JSON array SQLite
 * builds (`legs`).
 */
export interface Transaction {
  /** Its block; null while pending. */
  block?: string | null;
  /**
   * Unix ms this server recorded it, before its first broadcast: set
   * exactly on this server's sends, mined or not; null on every other.
   * Mining keeps it.
   */
  broadcasted_at?: number | null;
  chain: string;
  /** `{chain}.{network}.{txid}`. */
  id: string;
  /** Its kept legs, in order. */
  legs: Leg[];
  network: string;
  /** Its position in its block; null while pending. */
  order?: number | null;
  /** Its block's position; null while pending. */
  position?: number | null;
  /**
   * Why it reverted, when the chain said (`reverted`); null otherwise.
   * Stored as JSON, shown decoded.
   */
  reason?: string | null;
  /** 0 pending, 1 succeeded, 2 reverted. */
  state: number;
  /** Chain-native transaction id. */
  txid: string;
}

/** One `trigger` row; the API shows it as is. */
export interface Trigger {
  /**
   * What it does: `{"name": "send", "input": {"source": target, "asset":
   * id, "destination": target, "amount": amount}}`.
   */
  action: unknown;
  /** Chain name, as `GET /v1/assets` lists it. */
  chain: string;
  /**
   * When it acts: `{"since": {"seconds": …}}` and compares under
   * `all`/`any`/`not`.
   */
  check: unknown;
  /** Unix ms. */
  created_at: number;
  /** Whether it runs. */
  enabled: boolean;
  /**
   * Which of them it acts on: compares under `all`/`any`/`not`; null:
   * every one.
   */
  filter?: unknown | null;
  /** The batch it was created in: every trigger of one create shares it. */
  group: string;
  /** Its slug: 1 to 64 of `[a-z0-9-]`. */
  id: string;
  last_round: LastRound | null;
  /** Network name, as `GET /v1/assets` lists it. */
  network: string;
  /**
   * Which wallet indexes it acts on: `{"ids": […]}`, `{"asset": "…"}`,
   * `{"tag": "…"}`, `{"untagged": {}}`, `{"all": […]}`, `{"any": […]}`, `{"not": …}`.
   */
  selector: unknown;
  /** Unix ms. */
  updated_at: number;
}

/** `POST /v1/triggers` body: triggers of one network stored together, all or none. */
export interface TriggerBatch {
  /** One to 16 triggers, each with its `id`. */
  triggers: TriggerDefinition[];
}

/** `POST /v1/triggers`: the triggers created. */
export interface TriggerBatchCreated {
  /** The batch's triggers, in its order. */
  triggers: Trigger[];
}

/** A trigger as written: in a `POST` (with `id`) or as a `PUT` body. */
export interface TriggerDefinition {
  action: unknown;
  chain: string;
  check: unknown;
  /** Absent means `true` in a `POST` and the stored value in a `PUT`. */
  enabled?: boolean;
  filter?: unknown | null;
  /** Its slug; required in a `POST`, refused in a `PUT` (the path names it). */
  id?: string;
  network: string;
  selector: unknown;
}

/** `GET /v1/triggers`: a page of triggers. */
export interface TriggerList {
  /**
   * Pass as `cursor` for the next page; null on the last page. Always
   * present.
   */
  next_cursor: string | null;
  /** Triggers in id order. */
  triggers: Trigger[];
}

/**
 * One run of a trigger: when it started, the send jobs it queued and how
 * they ended.
 */
export interface TriggerRun {
  /** Its send jobs, in the order queued; a job no longer kept is left out. */
  jobs: RunJob[];
  outcome: RunOutcome | null;
  /** Unix ms. */
  started_at: number;
  /**
   * What its round saw: wallets selected, kept by the filter, whether
   * the check held, and send jobs queued.
   */
  stats: TriggerStats;
}

/** `GET /v1/triggers/{id}/runs`: a page of runs. */
export interface TriggerRunList {
  /**
   * Pass as `cursor` for the next page; null on the last page. Always
   * present.
   */
  next_cursor: string | null;
  /** Runs, latest first. */
  runs: TriggerRun[];
}

/**
 * What one round saw of a trigger: how many wallet indexes its selector
 * picked, how many of them its filter kept, whether its check held over
 * those, and how many effects its action returned.
 */
export interface TriggerStats {
  /** Whether its check held over the kept ones. */
  checked: boolean;
  /** Effects (jobs) its action returned. */
  jobs: number;
  /** How many of them its filter kept (all of them without a filter). */
  kept: number;
  /** Wallet indexes its selector picked. */
  selected: number;
}

/** A user's two-factor. */
export interface TwoFactor {
  /**
   * Unix ms its first code was entered; always present, null: pending,
   * not on yet.
   */
  confirmed_at: number | null;
  /** Unix ms it was started. */
  created_at: number;
}

/** A two-factor code. */
export interface TwoFactorCode {
  /** The 6 digits the authenticator app shows. */
  code: string;
}

/** `POST /v1/user/2fa`. */
export interface TwoFactorStarted {
  /** The `otpauth://` URI for an authenticator app (its QR code). */
  uri: string;
}

/** `PUT /v1/user` body: what changes. */
export interface UpdateOwnUserRequest {
  /**
   * The new password, 8 characters at least; the current one is not
   * asked.
   */
  password: string;
}

/** `PATCH /v1/users/{id}` body: what changes. */
export interface UpdateUserRequest {
  /** Disabled (it, its keys and every session refused), or enabled again. */
  disabled?: boolean;
  /** Its new scopes, packed, covered by the caller's. */
  scopes?: Record<string, string[]>;
}

/** `PATCH /v1/wallets/{id}/indexes/{asset}` body. */
export interface UpdateWalletIndexRequest {
  /**
   * `paused`: skipped, no facts kept for blocks while paused; `indexing`:
   * resumed from `paused` or `no_data` (clearing its reason), backfilling
   * what it missed. `no_data` is the indexer's to set.
   */
  index_state: IndexState;
}

/**
 * One `user` row. Its JSON shows neither the password hash (only whether
 * it has one, `login`) nor the session secret.
 */
export interface User {
  /** Unix ms. */
  created_at: number;
  /** Unix ms it was disabled: it, its keys and every session refused. */
  disabled_at?: number | null;
  /** Its login, unique. */
  email: string;
  /** A uuid v7. */
  id: string;
  /** Unix ms; every session issued in its second or before is refused. */
  invalidated_at?: number | null;
  /**
   * The argon2id hash of its password; `None`: no dashboard login. In
   * JSON, `login`: whether it has one.
   */
  login: boolean;
  /** Its name, as shown. */
  name: string;
  /**
   * The widest scopes it may issue, packed in JSON
   * (`{"com.hashinbox": ["wallets:read"]}`).
   */
  scopes: Record<string, string[]>;
}

/** One `user_key` row. Its JSON shows neither the secret nor its hash. */
export interface UserKey {
  /** Unix ms. */
  created_at: number;
  /** Unix ms it stops working; `None`: never. */
  expires_at?: number | null;
  /** `hip/…`: its public client id, a session's `kid` and `iss`. */
  id: string;
  /**
   * Unix ms; every session it issued in that second or before is
   * refused (rotated).
   */
  invalidated_at?: number | null;
  /** Unix ms it was last used; not kept yet. */
  last_used_at?: number | null;
  /** What it is for: `shop backend`. */
  name: string;
  /** Unix ms it was revoked: it and its sessions refused for good. */
  revoked_at?: number | null;
  /** What it may do, covered by its user's; packed in JSON. */
  scopes: Record<string, string[]>;
  /** The user that issued it. */
  user_id: string;
}

/** `GET /v1/users`: a page of users. */
export interface UserList {
  /**
   * Pass as `cursor` for the next page; null on the last page. Always
   * present.
   */
  next_cursor: string | null;
  /** Users in id (creation) order. */
  users: User[];
}

/** `GET /v1/user`. */
export interface UserRead {
  /** The calling key, when a key calls. */
  key?: UserKey;
  two_factor: TwoFactor | null;
  /** The caller's user. */
  user: User;
}

/** The server's version, and its public settings. */
export interface Version {
  /** True on a fresh install (no user yet); absent otherwise. */
  missing_root?: boolean | null;
  /**
   * Every public setting's value (its default when never written), by
   * key: `{"instance": "hashinbox"}`.
   */
  settings: Record<string, unknown>;
  /** The build's version: its git tag description, or the crate version. */
  version: string;
}

/**
 * One wallet, as the API shows it: an address, whether its key is kept,
 * its tags, and its indexes (each with its balances, progress and legs;
 * read by [`db::find`] and [`db::find_page`], empty from the other
 * reads). The key (`curve`, `secret`) is never serialized, and the API
 * reads leave it out. No `Debug`: it may hold the key.
 */
export interface Wallet {
  /** Canonical address text. */
  address: string;
  chain: string;
  /**
   * The caller's own reference for it (e.g. their customer id), 1 to 128
   * characters; not unique. Null when none was given.
   */
  external_id: string | null;
  /** `{chain}.{network}.{address}`: what every wallet route takes. */
  id: string;
  /** Its indexes by asset id (`native` or the token id). */
  indexes: Record<string, WalletIndex>;
  /** Whether this server holds its key and can send from it. */
  keyed: boolean;
  network: string;
  /** Its tags, sorted, each once, each [`is_tag`]. */
  tags: string[];
}

/**
 * One asset of one wallet being indexed, as every read answers it (the
 * API shows it as is): its columns, how far it is indexed against its
 * network's tip, its balances and its pending legs. All computed in SQL
 * (`wallet_index_with_balance`); amounts are exact atomic decimal text, never summed.
 * Positions are native (height or slot).
 */
export interface WalletIndex {
  /** The asset id. */
  asset: string;
  /**
   * Its confirmed balance: its last live mined leg's total at or below
   * `finality_at`, `0` without one; negative when indexed debits exceed
   * indexed credits (history before the start or a jump is unknown);
   * null while `finality_at` is unknown.
   */
  balance_confirmed?: string | null;
  /**
   * What it had received by then (that leg's `total_received`):
   * `balance_confirmed` is `balance_confirmed_received -
   * balance_confirmed_sent` plus its adjustments.
   */
  balance_confirmed_received?: string | null;
  /**
   * What it had received by then in USD, each leg at its price when
   * mined (that leg's `total_received_usd`; a leg without one adds 0).
   */
  balance_confirmed_received_usd?: string | null;
  /** What it had sent by then (fees included), the same way. */
  balance_confirmed_sent?: string | null;
  /** What it had sent by then in USD, the same way (`total_sent_usd`). */
  balance_confirmed_sent_usd?: string | null;
  /**
   * What it can spend: `balance_confirmed` less its outgoing legs not yet
   * in it (pending, or mined above `finality_at`); null while
   * `balance_confirmed` is.
   */
  balance_confirmed_spendable?: string | null;
  /**
   * What it will hold once every pending transaction lands: its newest
   * live mined leg's total, any block (`0` without one), with what this
   * server sent and is not mined yet, in and out; null before its first
   * block (`indexed_through`), as every balance is.
   */
  balance_pending?: string | null;
  /**
   * Blocks between `indexed_through` and the network's produced tip;
   * null before the first block or without a tip.
   */
  behind_tip?: number | null;
  /**
   * The start indexed from: the one asked for, or the first block the
   * node served when it no longer served that one.
   */
  birthday: number;
  /**
   * The network's final (confirmed) block: its indexer's, or a trigger
   * round's; null when unknown.
   */
  finality_at?: number | null;
  /** `{wallet_id}.{asset}`. */
  id: string;
  /** The last block indexed; null before the first. */
  indexed_through?: number | null;
  /** Why it is `no_data`; null otherwise. */
  reason?: string | null;
  /** The start asked for. */
  requested_from: number;
  state: IndexState;
  /** `{chain}.{network}.{address}`. */
  wallet_id: string;
}

/** `GET /v1/wallets`: a page of wallets. */
export interface WalletList {
  /**
   * Pass as `cursor` for the next page; null on the last page. Always
   * present.
   */
  next_cursor: string | null;
  /** Wallets in ID order. */
  wallets: Wallet[];
}

/** `PUT /v1/settings/{key}` body. */
export interface WriteSettingRequest {
  /** Its new value: JSON of the setting's type. */
  value: unknown;
}
